const anthropicText = (r) => {
  if (!r || !Array.isArray(r.content)) {
    const m = (r && r.error && (r.error.message || r.error.type || r.error.description)) || 'no response';
    return { ok: false, error: String(m).slice(0, 200) };
  }
  if (r.stop_reason === 'max_tokens') return { ok: false, error: 'answer truncated (max_tokens)' };
  if (r.stop_reason === 'refusal') return { ok: false, error: 'model declined the request' };
  if (r.stop_reason === 'pause_turn') return { ok: false, error: 'web search did not finish (pause_turn)' };
  const text = r.content.filter(b => b && b.type === 'text' && b.text).map(b => b.text).join('').trim();
  if (!text) return { ok: false, error: 'empty answer' };
  return { ok: true, text };
};
const stripFences = (t) => String(t).replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/, '');
const r = $input.item.json;
const mk = (o) => { const obs = o; return { json: { observation: Object.assign({ trigger_id: $('Load due web triggers').item.json.id }, obs) } }; };
const fail = (m) => mk({ ok: false, reason: String(m).slice(0, 300) });
const res = anthropicText(r);
if (!res.ok) return fail(res.error);
const text = stripFences(res.text);
const start = text.indexOf('{');
if (start < 0) return fail('no JSON object in model output');
let depth = 0, end = -1;
for (let i = start; i < text.length; i++) {
  if (text[i] === '{') depth++;
  else if (text[i] === '}') { depth--; if (depth === 0) { end = i; break; } }
}
if (end < 0) return fail('unbalanced JSON in model output');
let o;
try { o = JSON.parse(text.slice(start, end + 1)); } catch (e) { return fail('unparseable model output'); }
if (o.ok !== true) return mk({ ok: false, reason: String(o.reason || 'model reported cannot_determine').slice(0, 300) });
if (typeof o.value !== 'number' || !isFinite(o.value)) return fail('value is not a finite number');
return mk({ ok: true, value: o.value, unit: String(o.unit || ''), as_of: String(o.as_of || ''), source_url: String(o.source_url || '') });

const items = $input.all();
return [{ json: {
  run_ts: $('Load due web triggers').first().json.run_ts,
  observations: items.map(i => i.json.observation)
} }];

function uiRender(B, LANGS) {
  B = B || {};
  LANGS = LANGS || {};
  const T = B.t || {};
  const loc = B.locale || 'en-GB';
  // fn_ui_texts liefert fuer einen fehlenden Key den Key selbst -> das zaehlt hier als "nicht vorhanden".
  const has = (k) => Object.prototype.hasOwnProperty.call(T, k) && T[k] !== k;
  const t = (k) => (has(k) ? T[k] : String(k));
  const empty = has('core.fmt.empty') ? T['core.fmt.empty'] : '—';
  const isEmpty = (v) => v === null || v === undefined || v === '';
  // Platzhalter in EINEM Durchlauf: einfache Werte unveraendert (auch '' fuer optionale Zusaetze wie die Einheit),
  // nur typisierte Werte ({kind: money|date|enum|...}) laufen durch val(); null/undefined -> ''. Ein FEHLENDER
  // Parameter zaehlt wie undefined: n8n verwirft undefined-Felder beim Speichern des Summary-Objekts, sonst stuende
  // Rohtext wie "{isin}" auf der Karte (Owner 2026-10-22). Vertippte Parameter-Namen faengt der Build
  // (Assert-HitlTplParams in New-HitlLine/New-HitlNote/New-HitlSummary).
  function fill(txt, params) {
    return String(txt).replace(/\{(\w+)\}/g, (m, n) => {
      if (!params || !Object.prototype.hasOwnProperty.call(params, n)) return '';
      const p = params[n];
      if (p === null || p === undefined) return '';
      return (typeof p === 'object') ? val(p) : String(p);
    });
  }
  // sign = true (core.fn_ui_money p_sign): '+' vor positive Betraege (Gewinn seit Kauf); negative tragen ihr Minus ohnehin.
  function money(v, c, sign) {
    if (isEmpty(v)) return empty;
    const n = Number(v);
    if (!isFinite(n)) return String(v);
    const plus = (sign === true && n > 0) ? '+' : '';
    // Ohne gueltigen Waehrungscode KEIN stilles EUR (ein USD-Betrag sahe sonst wie Euro aus): Zahl + Rohcode.
    if (!(typeof c === 'string' && /^[A-Za-z]{3}$/.test(c))) return plus + num(v, 2) + (isEmpty(c) ? '' : ' ' + String(c));
    const cur = c.toUpperCase();
    try { return plus + Number(n).toLocaleString(loc,{style:'currency',currency:(/^[A-Za-z]{3}$/.test(cur)?cur:'EUR'),currencyDisplay:'narrowSymbol'}); } catch (e) { return plus + String(v) + ' ' + cur; }
  }
  function date(v) {
    if (isEmpty(v)) return empty;
    try { return ((m) => m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toLocaleDateString(loc, {timeZone:'UTC', year:'numeric', month:'2-digit', day:'2-digit'}) : String(v))(/^(\d{4})-(\d{2})-(\d{2})/.exec(String(v))); } catch (e) { return String(v); }
  }
  // Nachkommastellen, die der Wert selbst traegt (ohne Null-Schwanz der DB, z. B. numeric(18,8) "10.00000000" -> 0).
  function decimals(v) {
    const s = String(v).trim();
    const e = s.match(/^-?\d+(?:\.(\d+))?e-(\d+)$/i);
    if (e) return Math.min(20, (e[1] || '').length + Number(e[2]));
    const m = s.match(/\.(\d+)$/);
    return m ? Math.min(20, m[1].replace(/0+$/, '').length) : 0;
  }
  // digits < 0 = so viele Stellen wie der Wert hat (Stueckzahlen: Krypto bis 8 Stellen, nie gerundet).
  function num(v, digits, sign) {
    if (isEmpty(v)) return empty;
    const n = Number(v);
    if (!isFinite(n)) return String(v);
    const d = (Number(digits) < 0) ? decimals(v) : Math.max(0, Math.min(6, Number(digits) || 0));
    try { return n.toLocaleString(loc, { minimumFractionDigits: d, maximumFractionDigits: d, signDisplay: sign ? 'exceptZero' : 'auto' }); }
    catch (e) { return String(v); }
  }
  function val(x) {
    if (isEmpty(x)) return empty;
    if (typeof x !== 'object') return String(x);
    if (Array.isArray(x)) return x.length ? x.map(val).join(', ') : empty;
    const v = x.value;
    switch (x.kind) {
      case 'money': return money(v, x.currency, x.sign);
      case 'date': return date(v);
      case 'number': return num(v, x.digits, x.sign);
      case 'enum': {
        if (isEmpty(v)) return empty;
        const k = String(x.enum) + '.' + String(v).toLowerCase().replace(/[^a-z0-9_]+/g, '_');
        return has(k) ? T[k] : String(v);
      }
      case 'bool': return (v === true || v === 'true') ? t('core.fmt.yes')
        : ((v === false || v === 'false') ? t('core.fmt.no') : empty);
      case 'language': return isEmpty(v) ? empty : (LANGS[v] || String(v));
      case 'key': return isEmpty(v) ? empty : (has(v) ? T[v] : (x.fallback || String(v)));
      case 'tpl': return isEmpty(v) ? empty : fill(t(v), x.params);
      case 'removed': return t('core.fmt.removed');
      case 'list': return (Array.isArray(v) && v.length) ? v.map(val).join(', ') : empty;
      default: return isEmpty(v) ? empty : (Array.isArray(v) ? v.join(', ') : String(v));
    }
  }
  function msg(parts) {
    return (Array.isArray(parts) ? parts : [parts]).filter((p) => !isEmpty(p)).map(val).join(' ');
  }
  function lines(ls) {
    return (Array.isArray(ls) ? ls : []).map((l) => (l === null || l === undefined) ? ''
      : (Array.isArray(l) ? msg(l) : val(l))).join('\n');
  }
  return { T, loc, has, t, empty, isEmpty, fill, money, date, num, val, msg, lines };
}const m = $input.first().json;
const fired = JSON.parse(m.fired || '[]');
const info = JSON.parse(m.info || '[]');
const problems = JSON.parse(m.problems || '[]');
const U = uiRender(JSON.parse(m.ui || '{}'));
const domainPackage = {"career":"career","estate":"estate","finance":"finance"};
// Werte exakt (bis 6 Nachkommastellen, keine erzwungenen Nullen) im Owner-Locale; Nicht-Zahlen roh
const nv = (v) => U.isEmpty(v) ? '-' : (isFinite(Number(v)) ? Number(v).toLocaleString(U.loc, { maximumFractionDigits: 6 }) : String(v));
const withUnit = (v, unit) => nv(v) + (unit ? ' ' + unit : '');
const d = (iso) => U.date(iso);
const L = [U.t('core.monitor.title')];
if (fired.length) {
  L.push(''); L.push(U.t('core.monitor.fired'));
  for (const f of fired) {
    let detail;
    if (f.trigger_type === 'date') detail = U.fill(U.t('core.monitor.date_reached'), { date: d(f.due_date) });
    else if (f.trigger_type === 'drawdown') detail = U.fill(U.t('core.monitor.drawdown'), { pct: nv(f.drawdown_observed),
      reference: withUnit(f.reference_value, f.unit), value: withUnit(f.value, f.unit) });
    else detail = U.fill(U.t((f.previous_value !== undefined && f.previous_value !== null) ? 'core.monitor.threshold_previous' : 'core.monitor.threshold'),
      { value: withUnit(f.value, f.unit), comparator: (f.comparator === 'lte' ? '<=' : '>='), threshold: nv(f.threshold_value), previous: nv(f.previous_value) });
    L.push('• ' + f.label + ': ' + detail);
    if (f.source_url) L.push('  ' + U.fill(U.t(f.as_of ? 'core.monitor.source_as_of' : 'core.monitor.source'), { url: f.source_url, date: d(f.as_of) }));
    if (f.action_note) L.push('  ' + U.fill(U.t('core.monitor.action'), { note: f.action_note }));
    const pkg = domainPackage[f.domain];
    if (pkg) L.push('  -> ' + U.fill(U.t('core.monitor.advisor_hint'), { package: U.t(pkg + '.package.name') }));
  }
}
if (info.length) {
  L.push(''); L.push(U.t('core.monitor.info'));
  for (const i of info) {
    if (i.kind === 'date_warning') L.push('• ' + i.label + ': ' + U.fill(U.t('core.monitor.date_warning'), { days: nv(i.days_left), date: d(i.due_date) }) + (i.action_note ? ' - ' + i.action_note : ''));
    else L.push('• ' + i.label + ': ' + ((i.value !== undefined && i.value !== null) ? withUnit(i.value, i.unit) : '-')
      + (i.as_of ? ' ' + U.fill(U.t('core.monitor.value_as_of'), { date: d(i.as_of) }) : '') + (i.action_note ? ' - ' + i.action_note : ''));
  }
}
if (problems.length) {
  L.push(''); L.push(U.t('core.monitor.problems'));
  for (const p of problems) {
    L.push('• ' + p.label + ': ' + U.fill(U.t('core.monitor.problem'), { since: p.first_fail ? d(p.first_fail) : '?', streak: nv(p.fail_streak), reason: p.reason || '' }));
    L.push('  ' + U.fill(U.t('core.monitor.repair'), { label: p.label }));
  }
}
if (fired.length) { L.push(''); L.push(U.t('core.monitor.fired_note')); }
return [{ json: { message: L.join('\n') } }];
